import React, { useState, useEffect, lazy, Suspense, memo, useMemo, useCallback } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { AnimatePresence, motion } from 'framer-motion';
import './App.css';

// Context Providers
import { NotificationProvider } from './components/NotificationContext';
import { ThemeProvider, ThemeToggle, ThemeTransition } from './contexts/ThemeContext';
import { NavigationProvider } from './contexts/NavigationContext';

// Demo Data
import { demoStudyData, demoTasks, demoBookPages } from './data/demoData';

// Components
const DockBar = lazy(() => import('./components/DockBar'));
const ParallaxBackground = lazy(() => import('./components/ParallaxBackground'));
const ErrorBoundary = React.lazy(() => import('./components/ErrorBoundary'));

// Lazy loaded pages/views for better performance
const Dashboard = lazy(() => import('./pages/Dashboard'));
const Tasks = lazy(() => import('./pages/Tasks'));
const Pomodoro = lazy(() => import('./pages/Pomodoro'));
const Books = lazy(() => import('./pages/Books'));
const Profile = lazy(() => import('./pages/Profile'));
const Calendar = lazy(() => import('./pages/Calendar'));
const Statistics = lazy(() => import('./pages/Statistics'));

// Neural-themed loading component with animation
const NeuralLoadingFallback = memo(() => {
  const [dots, setDots] = useState('');
  
  useEffect(() => {
    const interval = setInterval(() => {
      setDots(prev => prev.length < 3 ? prev + '.' : '');
    }, 300);
    
    return () => clearInterval(interval);
  }, []);
  
  return (
    <div className="flex flex-col items-center justify-center min-h-[60vh]">
      <motion.div
        className="relative w-20 h-20"
        initial={{ opacity: 0.5 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.5, repeat: Infinity, repeatType: "reverse" }}
      >
        {/* Neural network loading animation */}
        <svg width="100%" height="100%" viewBox="0 0 100 100">
          {/* Central node */}
          <motion.circle
            cx="50"
            cy="50"
            r="8"
            fill="rgba(100, 200, 255, 0.8)"
            initial={{ r: 4 }}
            animate={{ r: 8, filter: "blur(2px)" }}
            transition={{ duration: 0.8, repeat: Infinity, repeatType: "reverse" }}
          />
          
          {/* Orbiting nodes */}
          {[...Array(6)].map((_, i) => {
            const angle = (i * (360 / 6)) * (Math.PI / 180);
            const delay = i * 0.1;
            
            return (
              <g key={`node-${i}`}>
                <motion.circle
                  cx={50 + 30 * Math.cos(angle)}
                  cy={50 + 30 * Math.sin(angle)}
                  r="4"
                  fill="rgba(100, 200, 255, 0.6)"
                  initial={{ opacity: 0.3, r: 2 }}
                  animate={{ opacity: 0.8, r: 4 }}
                  transition={{ 
                    duration: 0.8, 
                    repeat: Infinity, 
                    repeatType: "reverse",
                    delay
                  }}
                />
                
                {/* Connecting line */}
                <motion.line
                  x1="50"
                  y1="50"
                  x2={50 + 30 * Math.cos(angle)}
                  y2={50 + 30 * Math.sin(angle)}
                  stroke="rgba(100, 200, 255, 0.4)"
                  strokeWidth="1"
                  initial={{ pathLength: 0, opacity: 0.2 }}
                  animate={{ pathLength: 1, opacity: 0.7 }}
                  transition={{ 
                    duration: 1, 
                    repeat: Infinity, 
                    repeatType: "reverse",
                    delay
                  }}
                />
              </g>
            );
          })}
        </svg>
      </motion.div>
      
      <div className="text-center mt-6">
        <h2 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-neural-200 via-white to-neural-400">
          Neural Sync{dots}
        </h2>
        <p className="text-sm text-neural-400/70 mt-1">Optimizing neural pathways</p>
      </div>
    </div>
  );
});

// Performance status component
const PerformanceToggle = memo(({ lowPerformanceMode, togglePerformanceMode }) => {
  return (
    <motion.button 
      onClick={togglePerformanceMode}
      className="neural-button backdrop-blur-md bg-neural-900/40 border border-neural-400/30 text-white p-2 rounded-full flex items-center justify-center"
      title={lowPerformanceMode ? "Enable full animations" : "Reduce animations (improves performance)"}
      whileHover={{ scale: 1.05, boxShadow: "0 0 10px rgba(100, 200, 255, 0.4)" }}
      whileTap={{ scale: 0.95 }}
    >
      {lowPerformanceMode ? "🚀" : "🔥"}
      <motion.div 
        className="absolute inset-0 rounded-full"
        animate={{ 
          boxShadow: lowPerformanceMode ? 
            "inset 0 0 10px rgba(0, 255, 0, 0.3)" : 
            "inset 0 0 10px rgba(255, 0, 0, 0.3)" 
        }}
      />
    </motion.button>
  );
});

function App() {
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [lowPerformanceMode, setLowPerformanceMode] = useState(false);
  const [isAndroid, setIsAndroid] = useState(false);

  // Detect Android device on mount
  useEffect(() => {
    const userAgent = navigator.userAgent.toLowerCase();
    const isAndroidDevice = /android/i.test(userAgent);
    setIsAndroid(isAndroidDevice);
    
    // Auto-enable low performance mode on lower-end Android devices
    if (isAndroidDevice) {
      // Check if device is likely to be low-end by checking some performance indicators
      const isLowEndDevice = 
        !window.requestIdleCallback || 
        !window.requestAnimationFrame || 
        (navigator.deviceMemory && navigator.deviceMemory < 4);
      
      if (isLowEndDevice) {
        setLowPerformanceMode(true);
        document.documentElement.classList.add('low-performance-mode');
      }
    }
    
    // Add Android-specific meta tags
    if (isAndroidDevice) {
      const viewportMeta = document.querySelector('meta[name="viewport"]');
      if (viewportMeta) {
        viewportMeta.content = 'width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover';
      }
    }
  }, []);

  // Memoized state updates
  const handleSetActiveTab = useCallback((tab) => {
    console.log(`Setting active tab to: ${tab}`);
    
    // Handle edge cases for tab names
    const normalizedTab = tab === '' || tab === '/' ? 'dashboard' : tab;
    
    // Update the active tab state
    setActiveTab(normalizedTab);
    
    // Add developer console logging for debugging purposes
    if (process.env.NODE_ENV === 'development') {
      console.log(`Active tab updated to: ${normalizedTab}`);
    }
  }, []);

  // Optimize scrolling behavior 
  useEffect(() => {
    // Ensure proper scrolling behavior only once during initial render
    document.body.style.overflow = 'auto';
    document.body.style.height = 'auto';
    document.documentElement.style.overflow = 'auto'; 
    document.documentElement.style.height = 'auto';
    
    // Add optimized event listeners for scroll performance
    const handleScroll = () => {
      // Only process scroll events when needed, using requestAnimationFrame
      if (!window.requestAnimationScrollUpdate) {
        window.requestAnimationScrollUpdate = true;
        window.requestAnimationFrame(() => {
          // Scroll optimization logic could go here if needed
          window.requestAnimationScrollUpdate = false;
        });
      }
    };
    
    window.addEventListener('scroll', handleScroll, { passive: true });
    
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, []);

  // Memoized loading effect with reduced time
  useEffect(() => {
    // Using requestAnimationFrame for smoother loading transition
    const loadingTimeout = setTimeout(() => {
      requestAnimationFrame(() => setLoading(false));
    }, 400); // Reduced loading time

    return () => clearTimeout(loadingTimeout);
  }, []);

  // Toggle performance mode with memoization
  const togglePerformanceMode = useCallback(() => {
    setLowPerformanceMode(prevMode => {
      const newMode = !prevMode;
      if (newMode) {
        document.documentElement.classList.add('low-performance-mode');
      } else {
        document.documentElement.classList.remove('low-performance-mode');
      }
      return newMode;
    });
  }, []);

  // Memoized route rendering for improved performance
  const routes = useMemo(() => (
    <Routes>
      {/* Handle both root and dashboard routes */}
      <Route path="/" element={<Navigate to="/dashboard" replace />} />
      <Route path="/dashboard" element={
        <Dashboard 
          studyData={demoStudyData} 
          tasks={demoTasks}
          key="dashboard" // Force remount on navigation 
        />
      } />
      <Route path="/tasks" element={<Tasks tasks={demoTasks} />} />
      <Route path="/pomodoro" element={<Pomodoro tasks={demoTasks} />} />
      <Route path="/books" element={<Books pages={demoBookPages} />} />
      <Route path="/calendar" element={<Calendar />} />
      <Route path="/statistics" element={<Statistics />} />
      <Route path="/profile" element={<Profile studyData={demoStudyData} tasks={demoTasks} />} />
      <Route path="*" element={<Navigate to="/dashboard" replace />} />
    </Routes>
  ), []);

  return (
    <ThemeProvider>
      <ThemeTransition>
        <NotificationProvider>
          <NavigationProvider>
            <div className={`App relative min-h-screen overflow-x-hidden ${isAndroid ? 'android-device' : ''}`}>
              {/* Dynamic Background with Suspense */}
              <Suspense fallback={null}>
                <ParallaxBackground lowPerformanceMode={lowPerformanceMode || isAndroid} />
              </Suspense>
              
              {/* Loading Screen with Neural Animation */}
              {loading ? (
                <div className="loading absolute inset-0 flex items-center justify-center bg-neural-gradient z-50">
                  <NeuralLoadingFallback />
                </div>
              ) : (
                <>
                  {/* Theme and Performance Control Panel */}
                  <div className="fixed top-4 right-4 z-50 flex items-center space-x-2">
                    <Suspense fallback={null}>
                      <PerformanceToggle 
                        lowPerformanceMode={lowPerformanceMode} 
                        togglePerformanceMode={togglePerformanceMode} 
                      />
                    </Suspense>
                    <ThemeToggle className="neural-button backdrop-blur-md bg-neural-900/40 border border-neural-400/30 text-white p-2 rounded-full" />
                  </div>
                  
                  {/* Main Content Area with Optimized Rendering */}
                  <main 
                    className="pt-4 pb-16 px-2 md:px-4 min-h-screen overflow-y-auto overflow-x-hidden"
                    style={{
                      height: "100vh", 
                      position: "relative",
                      scrollBehavior: isAndroid ? "auto" : "smooth", // Use standard scrolling on Android for better performance
                      overscrollBehavior: "none", // Prevent browser bounce for better performance
                      WebkitOverflowScrolling: 'touch', // Better scroll handling on mobile
                      touchAction: 'pan-y', // Allow vertical scrolling but disable horizontal
                    }}
                  >
                    <AnimatePresence mode="wait" initial={false}>
                      <Suspense fallback={<NeuralLoadingFallback />}>
                        <ErrorBoundary>
                          {routes}
                        </ErrorBoundary>
                      </Suspense>
                    </AnimatePresence>
                  </main>
                  
                  {/* Dock Bar with Lazy Loading */}
                  <Suspense fallback={null}>
                    <DockBar activeTab={activeTab} setActiveTab={handleSetActiveTab} />
                  </Suspense>
                </>
              )}
            </div>
          </NavigationProvider>
        </NotificationProvider>
      </ThemeTransition>
    </ThemeProvider>
  );
}

export default memo(App);
